INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (1, 'Day 1: Self Introduction', 'روز ۱: معرفی خود', 'basics', 1, 'You''re meeting someone new for the first time. Introduce yourself and find out about them.', 'با یه نفر جدید آشنا می‌شید. خودتون رو معرفی کنید و درباره‌شون بیشتر بدونید.', 'Present tense: sein, heißen, kommen aus', 'زمان حال: sein، heißen، kommen aus', 'A1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (2, 'Day 2: Greetings & Farewells', 'روز ۲: سلام و خداحافظی', 'basics', 2, 'You''re greeting different people throughout the day. Practice formal and informal ways to say hello and goodbye.', 'در طول روز با افراد مختلف روبرو می‌شید. روش‌های رسمی و غیررسمی سلام و خداحافظی رو تمرین کنید.', 'Register: formal (Sie) vs. informal (du) greetings', 'ادب رسمی (Sie) در مقابل غیررسمی (du)', 'A1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (3, 'Day 3: How Are You?', 'روز ۳: حال شما چطور است؟', 'basics', 3, 'A neighbor stops you on the street. Exchange pleasantries and ask how they''re doing.', 'یه همسایه تو خیابون جلوتون رو می‌گیره. احوال‌پرسی کنید و بپرسید حالشون چطوره.', 'Short answers: gut, nicht so gut, danke', 'جواب‌های کوتاه: gut، nicht so gut، danke', 'A1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (4, 'Day 4: Numbers & Age', 'روز ۴: اعداد و سن', 'basics', 4, 'You''re filling out a form and chatting about ages and phone numbers.', 'دارید یه فرم پر می‌کنید و درباره سن و شماره تلفن صحبت می‌کنید.', 'Cardinal numbers 1–100 + Ich bin … Jahre alt', 'اعداد ۱ تا ۱۰۰ + Ich bin … Jahre alt', 'A1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (5, 'Day 5: Days, Months & Dates', 'روز ۵: روزها، ماه‌ها و تاریخ‌ها', 'basics', 5, 'You''re making plans and need to talk about days of the week, months, and important dates.', 'دارید برنامه‌ریزی می‌کنید و باید درباره روزهای هفته، ماه‌ها و تاریخ‌های مهم صحبت کنید.', 'Nominative: Heute ist Montag / Mein Geburtstag ist am…', 'حالت اسمی: Heute ist Montag / Mein Geburtstag ist am…', 'A1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (6, 'Day 6: Family Members', 'روز ۶: اعضای خانواده', 'basics', 6, 'A new friend asks about your family. Describe who you live with and your family situation.', 'یه دوست جدید درباره خانواده‌تون می‌پرسه. توصیف کنید با چه کسی زندگی می‌کنید.', 'Possessive pronouns: mein/meine/mein', 'ضمایر ملکی: mein/meine/mein', 'A1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (7, 'Day 7: At the Café', 'روز ۷: کافه', 'basics', 7, 'You walk into a cozy café in Berlin. Order a drink and settle in.', 'وارد یه کافه دنج در برلین می‌شید. یه نوشیدنی سفارش بدید و راحت بنشینید.', 'Ordering: Ich hätte gerne… / Einmal … bitte', 'سفارش دادن: Ich hätte gerne… / Einmal … bitte', 'A1+');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (8, 'Day 8: Asking for Help', 'روز ۸: کمک خواستن', 'basics', 8, 'You''re lost in an unfamiliar part of town. Stop someone and ask for help.', 'تو یه محله ناآشنا گم شدید. یه نفر رو متوقف کنید و کمک بخواید.', 'Modal verb: können + infinitive', 'فعل کمکی können + مصدر', 'A1+');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (9, 'Day 9: Understanding & Clarifying', 'روز ۹: فهمیدن و شفاف‌سازی', 'basics', 9, 'Someone is speaking too fast for you to understand. Ask them to slow down and repeat.', 'یه نفر خیلی سریع صحبت می‌کنه. ازشون بخواید کندتر بگن و تکرار کنن.', 'Imperative: Bitte langsamer! / Wiederholen Sie!', 'امری: Bitte langsamer! / Wiederholen Sie!', 'A1+');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (10, 'Day 10: Problems & Apologies', 'روز ۱۰: مشکلات و عذرخواهی', 'basics', 10, 'You''re running late for a meeting and something has gone wrong. Apologize and explain.', 'دیر به جلسه رسیدید و یه مشکلی پیش اومده. عذرخواهی کنید و توضیح بدید.', 'Negation with nicht + kein problem', 'نفی با nicht + kein Problem', 'A1+');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (11, 'Day 11: Basic Questions', 'روز ۱۱: سوالات پایه', 'basics', 11, 'You''ve just met an interesting person at an event. Ask questions to learn more about them.', 'تو یه رویداد با یه نفر جالب آشنا شدید. سوال بپرسید تا بیشتر بشناسیدشون.', 'W-question words: Wer, Was, Wo, Wann, Wie, Warum', 'کلمات پرسشی: Wer، Was، Wo، Wann، Wie، Warum', 'A1+');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (12, 'Day 12: Colors & Adjectives', 'روز ۱۲: رنگ‌ها و صفت‌ها', 'basics', 12, 'You''re describing objects and places around you using colors and basic adjectives.', 'دارید اشیاء و مکان‌های اطرافتون رو با رنگ‌ها و صفات پایه توصیف می‌کنید.', 'Predicate adjectives: Das ist groß / klein / alt / neu', 'صفت خبری: Das ist groß / klein / alt / neu', 'A1+');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (13, 'Day 13: Asking Directions (Basic)', 'روز ۱۳: پرسیدن مسیر (پایه)', 'survival', 13, 'You need to find a pharmacy in an unfamiliar neighborhood. Ask a passerby for simple directions.', 'باید یه داروخانه تو محله ناآشنا پیدا کنید. از یه رهگذر مسیر ساده بخواید.', 'Imperative directions: Gehen Sie geradeaus / links / rechts', 'جملات امری مسیر: Gehen Sie geradeaus / links / rechts', 'A1+');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (14, 'Day 14: Asking Directions (Advanced)', 'روز ۱۴: پرسیدن مسیر (پیشرفته)', 'survival', 14, 'You''re looking for the post office in a complex area. Get more detailed directions using landmarks.', 'دارید دنبال اداره پست تو یه منطقه پیچیده می‌گردید. مسیر دقیق‌تر با نشانه‌های محلی بگیرید.', 'Location prepositions: neben, gegenüber, an der, in der Nähe von', 'حروف اضافه مکان: neben، gegenüber، an der، in der Nähe von', 'A1+');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (15, 'Day 15: Public Transportation', 'روز ۱۵: حمل‌ونقل عمومی', 'survival', 15, 'You''re at a bus stop and need to find your connection. Ask about departure times and routes.', 'تو ایستگاه اتوبوس هستید و باید مسیر اتصالی رو پیدا کنید. درباره زمان حرکت و مسیر بپرسید.', 'Time questions: Wann fährt…? / Um wie viel Uhr…?', 'سوالات زمانی: Wann fährt…? / Um wie viel Uhr…?', 'A1+');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (16, 'Day 16: By Taxi or Rideshare', 'روز ۱۶: با تاکسی یا اشتراک سواری', 'survival', 16, 'You''ve just arrived at the airport and need to get to your hotel. Hail a taxi and discuss the fare.', 'تازه وارد فرودگاه شدید و باید به هتل برسید. تاکسی بگیرید و درباره کرایه صحبت کنید.', 'Dative contractions: zum / zur + destination', 'مخفف‌های حالت مفعولی غیرمستقیم: zum / zur + مقصد', 'A1+');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (17, 'Day 17: At the Airport', 'روز ۱۷: در فرودگاه', 'survival', 17, 'You''re checking in for your flight. Navigate check-in, baggage drop-off, and finding your gate.', 'دارید برای پروازتون چک‌این می‌کنید. چک‌این، تحویل بار و پیدا کردن گیت رو مدیریت کنید.', 'Compound nouns: Gepäckaufgabe, Sicherheitskontrolle, Abfluggate', 'اسم‌های مرکب: Gepäckaufgabe، Sicherheitskontrolle، Abfluggate', 'A1+');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (18, 'Day 18: Weather & Small Talk', 'روز ۱۸: آب‌وهوا و صحبت‌های روزمره', 'survival', 18, 'You''re chatting with a neighbor about today''s weather and plans for the week ahead.', 'با یه همسایه درباره آب‌وهوای امروز و برنامه‌های هفته پیش رو صحبت می‌کنید.', 'Weather verbs: Es regnet / Es schneit / Die Sonne scheint', 'فعل‌های آب‌وهوا: Es regnet / Es schneit / Die Sonne scheint', 'A1+');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (19, 'Day 19: Morning Routine', 'روز ۱۹: روتین صبحگاهی', 'survival', 19, 'You''re describing your daily morning routine to a language exchange partner.', 'دارید روتین صبحگاهی روزانه‌تون رو برای شریک تبادل زبانی توصیف می‌کنید.', 'Reflexive verbs: sich duschen, sich anziehen, sich vorbereiten', 'فعل‌های انعکاسی: sich duschen، sich anziehen، sich vorbereiten', 'A2');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (20, 'Day 20: At Home', 'روز ۲۰: در خانه', 'survival', 20, 'A friend is visiting your apartment for the first time. Show them around the rooms.', 'یه دوست برای اولین بار به آپارتمانتون می‌آد. خونه رو بهشون نشون بدید.', 'Location with im/in der: im Wohnzimmer, in der Küche', 'مکان با im/in der: im Wohnzimmer، in der Küche', 'A2');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (21, 'Day 21: Meals & Cooking', 'روز ۲۱: وعده‌های غذایی و آشپزی', 'survival', 21, 'A friend comes over for dinner. Chat about what you''re cooking and whether they''re hungry.', 'یه دوست برای شام می‌آد. درباره آنچه می‌پزید و اینکه گرسنه‌ان صحبت کنید.', 'Haben + question: Hast du Hunger? / Hast du Zeit?', 'haben + سوال: Hast du Hunger? / Hast du Zeit?', 'A2');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (22, 'Day 22: Time & Appointments', 'روز ۲۲: زمان و قرارملاقات‌ها', 'survival', 22, 'You''re trying to schedule a meeting with a colleague. Agree on a time that works for both.', 'دارید سعی می‌کنید با یه همکار قرار ملاقات بگذارید. یه زمان مناسب برای هر دوتون پیدا کنید.', 'Time expressions: um + time, Wann passt es dir?', 'عبارات زمانی: um + زمان، Wann passt es dir?', 'A2');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (23, 'Day 23: Social Small Talk', 'روز ۲۳: صحبت‌های اجتماعی', 'survival', 23, 'You''re at a party and start chatting with someone you''ve just met. Make some small talk.', 'تو یه مهمانی هستید و با یه نفر که تازه باهاش آشنا شدید صحبت می‌کنید.', 'Perfekt tense: Wie lange bist du schon hier? / Ich war…', 'زمان گذشته (Perfekt): Wie lange bist du schon hier? / Ich war…', 'A2');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (24, 'Day 24: Hobbies & Free Time', 'روز ۲۴: سرگرمی‌ها و وقت آزاد', 'survival', 24, 'You''re getting to know a new colleague over coffee. Talk about hobbies and free time.', 'دارید با یه همکار جدید سر قهوه آشنا می‌شید. درباره سرگرمی‌ها و اوقات فراغت صحبت کنید.', 'Gerne + infinitive for habitual likes', 'gerne + مصدر برای علاقه‌های معمول', 'A2');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (25, 'Day 25: Making Plans with Friends', 'روز ۲۵: برنامه‌ریزی با دوستان', 'survival', 25, 'It''s Thursday evening. You''re arranging plans with a friend for the weekend.', 'شب پنجشنبه‌ست. دارید با یه دوست برای آخر هفته برنامه‌ریزی می‌کنید.', 'Modal wollen + Lass uns + infinitive', 'فعل کمکی wollen + Lass uns + مصدر', 'A2');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (26, 'Day 26: Money & Prices', 'روز ۲۶: پول و قیمت‌ها', 'survival', 26, 'You''re shopping at a weekend market. Ask about prices and pay for your items.', 'دارید تو یه بازار آخر هفته خرید می‌کنید. درباره قیمت‌ها بپرسید و پول بدید.', 'Interrogative: Wie viel kostet…? + Ich zahle bar/mit Karte', 'پرسشی: Wie viel kostet…? + Ich zahle bar/mit Karte', 'A2');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (27, 'Day 27: At the Supermarket', 'روز ۲۷: در سوپرمارکت', 'survival', 27, 'You''re at the supermarket but can''t find what you need. Ask a staff member for help.', 'تو سوپرمارکت هستید ولی چیزی که نیاز دارید رو پیدا نمی‌کنید. از یه کارمند کمک بخواید.', 'Accusative with finden: Wo finde ich den/die/das…?', 'حالت مفعولی مستقیم با finden: Wo finde ich den/die/das…?', 'A2');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (28, 'Day 28: At the Bakery', 'روز ۲۸: در نانوایی', 'survival', 28, 'It''s Saturday morning and you''re at the weekly farmers'' market. Buy some fresh bread and pastries.', 'صبح شنبه‌ست و تو بازار هفتگی هستید. کمی نان تازه و شیرینی بخرید.', 'Partitive: 200 Gramm, ein Stück, eine Scheibe', 'کمی/مقداری: 200 Gramm، ein Stück، eine Scheibe', 'A2');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (29, 'Day 29: Shopping for Clothes', 'روز ۲۹: خرید لباس', 'survival', 29, 'You''re in a clothing store and want to try something on. Talk to the sales assistant.', 'تو یه مغازه لباس هستید و می‌خواید چیزی رو امتحان کنید. با فروشنده صحبت کنید.', 'Modal können: Kann ich das anprobieren? / Haben Sie…?', 'فعل کمکی können: Kann ich das anprobieren? / Haben Sie…?', 'A2');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (30, 'Day 30: Shopping for Electronics', 'روز ۳۰: خرید لوازم الکترونیکی', 'survival', 30, 'You need a new laptop charger. Ask about availability, warranty, and payment options.', 'یه شارژر لپ‌تاپ جدید نیاز دارید. درباره موجودی، گارانتی و روش‌های پرداخت بپرسید.', 'Wie lange ist die Garantie? / Können Sie…? – polite questions', 'Wie lange ist die Garantie? / Können Sie…? – سوالات مودبانه', 'A2');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (31, 'Day 31: Making Decisions', 'روز ۳۱: تصمیم‌گیری', 'survival', 31, 'You''re in a shop and can''t quite decide between two items. Think out loud and finally choose.', 'تو یه مغازه هستید و بین دو چیز نمی‌تونید تصمیم بگیرید. با خودتون فکر کنید و انتخاب کنید.', 'Decision making: Ich nehme das / Ich muss noch überlegen', 'تصمیم‌گیری: Ich nehme das / Ich muss noch überlegen', 'A2');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (32, 'Day 32: At Work (Casual)', 'روز ۳۲: سر کار (معمولی)', 'scenarios', 32, 'It''s Monday morning at the office. Catch up with a colleague about tasks and pending messages.', 'صبح دوشنبه‌ست تو اداره. با یه همکار درباره وظایف و پیام‌های در انتظار صحبت کنید.', 'Separable verbs: schicken, erledigen, vorbereiten', 'فعل‌های جداشدنی: schicken، erledigen، vorbereiten', 'A2+');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (33, 'Day 33: Phone Conversation', 'روز ۳۳: مکالمه تلفنی', 'scenarios', 33, 'You need to speak to someone at a company. Call them, navigate the receptionist, and leave a message.', 'باید با یه نفر توی یه شرکت صحبت کنید. زنگ بزنید، از پذیرش عبور کنید و پیام بذارید.', 'Phone phrases: Hier spricht… / Kann ich… sprechen? / Ich rufe zurück', 'عبارات تلفنی: Hier spricht… / Kann ich… sprechen? / Ich rufe zurück', 'A2+');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (34, 'Day 34: Emails & Messages', 'روز ۳۴: ایمیل‌ها و پیام‌ها', 'scenarios', 34, 'You need to write a professional email to a business contact. Compose a polite, formal message.', 'باید یه ایمیل حرفه‌ای به یه مخاطب تجاری بنویسید. یه پیام مودبانه و رسمی بنویسید.', 'Formal salutations: Sehr geehrte/r… / Mit freundlichen Grüßen', 'تعارف‌های رسمی: Sehr geehrte/r… / Mit freundlichen Grüßen', 'A2+');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (35, 'Day 35: Asking for Opinions', 'روز ۳۵: نظرخواهی', 'scenarios', 35, 'You''re at a new restaurant with a friend. Share opinions about the food and atmosphere.', 'با یه دوست تو یه رستوران جدید هستید. نظرتون درباره غذا و فضا رو بگید.', 'Opinion verbs: denken, finden, meinen + Ich stimme zu', 'فعل‌های نظر: denken، finden، meinen + Ich stimme zu', 'A2+');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (36, 'Day 36: Study & School', 'روز ۳۶: تحصیل و مدرسه', 'scenarios', 36, 'You want to join a German language school. Ask about levels, schedules, and how to enroll.', 'می‌خواید به یه آموزشگاه زبان آلمانی بپیوندید. درباره سطوح، برنامه‌ها و نحوه ثبت‌نام بپرسید.', 'Ich lerne + subject / Welches Niveau haben Sie?', 'Ich lerne + موضوع / Welches Niveau haben Sie?', 'A2+');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (37, 'Day 37: Rescheduling & Availability', 'روز ۳۷: تغییر برنامه و موجود بودن', 'scenarios', 37, 'Something has come up and you need to reschedule a work meeting. Handle it professionally.', 'یه اتفاقی افتاده و باید یه جلسه کاری رو جابجا کنید. حرفه‌ای باهاش کنار بیاید.', 'Conditional: Könnten wir…? / Würde … passen?', 'شرطی: Könnten wir…? / Würde … passen?', 'A2+');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (38, 'Day 38: Health & Feelings', 'روز ۳۸: سلامت و احساسات', 'scenarios', 38, 'You''re not feeling well and a colleague notices. Explain your symptoms and decide what to do.', 'حالتون خوب نیست و یه همکار متوجه می‌شه. علائمتون رو توضیح بدید و تصمیم بگیرید چیکار کنید.', 'Sich fühlen + adjective: Ich fühle mich müde / krank', 'sich fühlen + صفت: Ich fühle mich müde / krank', 'A2+');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (39, 'Day 39: At the Doctor', 'روز ۳۹: پیش دکتر', 'scenarios', 39, 'You have an appointment with your GP. Describe your symptoms and receive medical advice.', 'نوبت پزشک عمومی دارید. علائمتون رو توصیف کنید و توصیه پزشکی بگیرید.', 'Seit + dative: Seit wann haben Sie die Schmerzen?', 'seit + حالت مفعولی غیرمستقیم: Seit wann haben Sie die Schmerzen?', 'A2+');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (40, 'Day 40: At the Pharmacy', 'روز ۴۰: در داروخانه', 'scenarios', 40, 'You have a cold and need something from the pharmacy. Describe symptoms and ask for a remedy.', 'سرما خوردید و از داروخانه چیزی نیاز دارید. علائم رو بگید و داروی مناسب بخواید.', 'Haben Sie etwas gegen…? + Dosierung/Einnahme instructions', 'Haben Sie etwas gegen…? + دستورالعمل دوز/مصرف', 'A2+');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (41, 'Day 41: At the Dentist', 'روز ۴۱: پیش دندانپزشک', 'scenarios', 41, 'Your tooth has been hurting for two days. Call the dentist, describe the pain, and make an appointment.', 'دندونتون دو روزه درد می‌کنه. به دندونپزشک زنگ بزنید، درد رو توصیف کنید و نوبت بگیرید.', 'Pain expressions: tut weh, schmerzt + body vocabulary', 'عبارات درد: tut weh، schmerzt + واژگان اندام بدن', 'A2+');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (42, 'Day 42: Sports & Exercise', 'روز ۴۲: ورزش و تمرین', 'scenarios', 42, 'You''ve joined a gym and are chatting with another member about fitness routines and goals.', 'به باشگاه پیوستید و با یه عضو دیگه درباره برنامه ورزشی و اهداف صحبت می‌کنید.', 'Frequency adverbs: oft, manchmal, nie + Wie oft pro Woche?', 'قیدهای تکرار: oft، manchmal، nie + Wie oft pro Woche?', 'A2+');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (43, 'Day 43: Food & Dietary Preferences', 'روز ۴۳: غذا و ترجیحات رژیمی', 'scenarios', 43, 'You''re at a restaurant with dietary restrictions. Make sure the waiter fully understands your needs.', 'تو رستوران هستید و محدودیت غذایی دارید. مطمئن بشید که گارسون کاملاً نیازهاتون رو می‌فهمه.', 'Negation with kein: Ich esse kein Fleisch / keine Milch', 'نفی با kein: Ich esse kein Fleisch / keine Milch', 'A2+');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (44, 'Day 44: At the Restaurant', 'روز ۴۴: در رستوران', 'scenarios', 44, 'You''ve booked a table at a nice restaurant. Order food, ask for the chef''s recommendations, and pay.', 'میز تو یه رستوران خوب رزرو کردید. غذا سفارش بدید، پیشنهاد سرآشپز رو بپرسید و حساب کنید.', 'Konjunktiv II: Ich hätte gerne… / Könnten Sie mir empfehlen…?', 'وجه التزامی II: Ich hätte gerne… / Könnten Sie mir empfehlen…?', 'B1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (45, 'Day 45: At the Café (Extended)', 'روز ۴۵: در کافه (گسترده)', 'scenarios', 45, 'You''re settling in at a café to work for a couple of hours. Order, ask about Wi-Fi, and get comfortable.', 'دارید تو یه کافه مستقر می‌شید تا چند ساعت کار کنید. سفارش بدید، درباره وای‌فای بپرسید و راحت باشید.', 'Extended polite requests + ob-clauses: Wissen Sie, ob…?', 'درخواست‌های مودبانه گسترش‌یافته + جملات ob: Wissen Sie, ob…?', 'B1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (46, 'Day 46: Birthday Party', 'روز ۴۶: جشن تولد', 'scenarios', 46, 'You''ve been invited to a colleague''s birthday party. Bring a gift and join in the celebrations.', 'به مهمانی تولد یه همکار دعوت شدید. یه هدیه بیارید و توی جشن شرکت کنید.', 'Congratulations phrases + Dative after für: Herzlichen Glückwunsch zum…', 'عبارات تبریک + حالت مفعولی غیرمستقیم بعد از für', 'B1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (47, 'Day 47: Cultural Events & Cinema', 'روز ۴۷: رویدادهای فرهنگی و سینما', 'scenarios', 47, 'You''re buying cinema tickets for tonight''s showing. Choose a film and get the best available seats.', 'دارید بلیت سینما برای نمایش امشب می‌خرید. یه فیلم انتخاب کنید و بهترین صندلی‌های موجود رو بگیرید.', 'Time clauses: Wann beginnt…? + Ticket and booking vocabulary', 'جملات زمانی: Wann beginnt…? + واژگان بلیت و رزرو', 'B1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (48, 'Day 48: Complimenting & Small Talk', 'روز ۴۸: تعریف کردن و صحبت‌های سبک', 'scenarios', 48, 'You''re at a social gathering and meet someone new. Pay compliments and strike up a conversation.', 'تو یه گردهمایی اجتماعی هستید و با یه نفر جدید آشنا می‌شید. تعریف کنید و مکالمه شروع کنید.', 'Superlatives + Das sieht toll aus! / Wie lange wohnst du schon hier?', 'عالی‌ترین درجه + Das sieht toll aus! / Wie lange wohnst du schon hier?', 'B1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (49, 'Day 49: Weekend Plans', 'روز ۴۹: برنامه‌های آخر هفته', 'scenarios', 49, 'It''s Friday afternoon. Chat with a friend about what you''re both doing this weekend.', 'بعدازظهر جمعه‌ست. با یه دوست درباره برنامه‌های آخر هفته‌تون صحبت کنید.', 'Future with werden / present tense for near future plans', 'آینده با werden / زمان حال برای برنامه‌های نزدیک آینده', 'B1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (50, 'Day 50: Hotel Booking', 'روز ۵۰: رزرو هتل', 'advanced', 50, 'You''re calling a hotel in Munich to book a room for a business trip next week.', 'دارید به یه هتل در مونیخ زنگ می‌زنید تا اتاقی برای سفر کاری هفته آینده رزرو کنید.', 'Haben Sie…frei? / Ich möchte … reservieren + hotel vocabulary', 'Haben Sie…frei? / Ich möchte … reservieren + واژگان هتل', 'B1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (51, 'Day 51: At the Bank', 'روز ۵۱: در بانک', 'advanced', 51, 'You need to open a current account at a German bank. Ask all the right questions and fill in the forms.', 'باید یه حساب جاری در یه بانک آلمانی باز کنید. سوالات لازم رو بپرسید و فرم‌ها رو پر کنید.', 'Administrative questions + Wie lange dauert das? formal register', 'سوالات اداری + Wie lange dauert das? سبک رسمی', 'B1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (52, 'Day 52: At the Post Office', 'روز ۵۲: در اداره پست', 'advanced', 52, 'You need to send a parcel to Iran. Weigh it, fill in the customs form, and choose a delivery option.', 'باید یه بسته به ایران بفرستید. وزن کنید، فرم گمرک پر کنید و گزینه ارسال رو انتخاب کنید.', 'Weight and dimensions + Customs vocabulary: Zollformular, versichern', 'وزن و ابعاد + واژگان گمرک: Zollformular، versichern', 'B1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (53, 'Day 53: Renting a Car', 'روز ۵۳: اجاره ماشین', 'advanced', 53, 'You''re at a car rental counter at the airport. Choose a vehicle class and sort out insurance.', 'تو باجه اجاره خودرو در فرودگاه هستید. کلاس خودرو رو انتخاب کنید و بیمه رو مرتب کنید.', 'Vehicle class + Insurance: Vollkasko, Teilkasko + Rückgabe', 'کلاس خودرو + بیمه: Vollkasko، Teilkasko + Rückgabe', 'B1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (54, 'Day 54: Enrolling in a Course', 'روز ۵۴: ثبت‌نام در یک دوره', 'advanced', 54, 'You want to join a language school. Ask about the placement test, class sizes, timetable, and fees.', 'می‌خواید به یه آموزشگاه زبان بپیوندید. درباره آزمون تعیین سطح، اندازه کلاس، برنامه و هزینه بپرسید.', 'Level assessment + Anmelden: Welches Niveau haben Sie? / Ich möchte mich anmelden', 'ارزیابی سطح + Anmelden: Welches Niveau haben Sie? / Ich möchte mich anmelden', 'B1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (55, 'Day 55: Review Day', 'روز ۵۵: روز مرور', 'advanced', 55, 'A busy day of mixed situations. You''ll revisit key phrases and structures from the first 54 lessons.', 'یه روز پر از موقعیت‌های مختلف. عبارات و ساختارهای کلیدی از ۵۴ درس اول رو مرور می‌کنید.', 'Mixed review: key structures from Days 1–54', 'مرور ترکیبی: ساختارهای کلیدی از روز ۱ تا ۵۴', 'B1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (56, 'Day 56: Renting an Apartment', 'روز ۵۶: اجاره آپارتمان', 'advanced', 56, 'You''ve found a flat you like online. Visit the apartment and negotiate the rental terms with the landlord.', 'یه آپارتمان آنلاین پیدا کردید. از آپارتمان بازدید کنید و با صاحبخانه درباره شرایط اجاره مذاکره کنید.', 'Compound nouns: Kaltmiete, Nebenkosten + Kündigungsfrist', 'اسم‌های مرکب: Kaltmiete، Nebenkosten + Kündigungsfrist', 'B1+');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (57, 'Day 57: Technology Problems', 'روز ۵۷: مشکلات فناوری', 'advanced', 57, 'Your internet has gone down and you''ve been without connection for hours. Call the provider for help.', 'اینترنتتون قطع شده و چند ساعته بدون اتصال هستید. با ارائه‌دهنده تماس بگیرید.', 'Troubleshooting: Können Sie…neustarten? + Seit wann? / Störungsbereich', 'عیب‌یابی: Können Sie…neustarten? + Seit wann? / Störungsbereich', 'B1+');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (58, 'Day 58: Travel Problems', 'روز ۵۸: مشکلات سفر', 'advanced', 58, 'At the station you realise you''ve missed your train and your flight is delayed. Get help from the information desk.', 'تو ایستگاه متوجه می‌شید قطارتون رو از دست دادید و پروازتون تأخیر داره. از باجه اطلاعات کمک بگیرید.', 'Reporting problems: Ich habe verpasst / Mein Flug hat Verspätung', 'گزارش مشکلات: Ich habe verpasst / Mein Flug hat Verspätung', 'B1+');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (59, 'Day 59: Job Interview', 'روز ۵۹: مصاحبه شغلی', 'advanced', 59, 'You have a job interview at a German company. Answer questions about your experience and motivation.', 'مصاحبه شغلی در یه شرکت آلمانی دارید. به سوالات درباره تجربه و انگیزه‌تون جواب بدید.', 'Konjunktiv II for politeness: Ich würde … / Könnten Sie…?', 'وجه التزامی II برای ادب: Ich würde … / Könnten Sie…?', 'B1+');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (60, 'Day 60: Emergency Situations', 'روز ۶۰: موقعیت‌های اضطراری', 'advanced', 60, 'Your wallet has been stolen while sightseeing. Report the theft to the police and contact your embassy.', 'موقع گردشگری کیف پولتون دزدیده شده. دزدی رو به پلیس گزارش بدید و با سفارت‌خانه تماس بگیرید.', 'Urgent requests + Reporting: Ich möchte Anzeige erstatten / Können Sie mir helfen?', 'درخواست‌های فوری + گزارش: Ich möchte Anzeige erstatten / Können Sie mir helfen?', 'B1+');
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 0, 'received', 'Hallo! Darf ich fragen, wie du heißt?', NULL, 'Hello! May I ask what your name is?', 'سلام! می‌تونم بپرسم اسمت چیه؟', NULL, NULL FROM lessons WHERE day = 1;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 1, 'sent', NULL, 'Hallo! Mein Name ist Lukas.', 'Hello! My name is Lukas.', 'سلام! اسم من لوکاس هست.', NULL, NULL FROM lessons WHERE day = 1;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 2, 'received', 'Woher kommst du?', NULL, 'Where are you from?', 'اهل کجایی؟', NULL, NULL FROM lessons WHERE day = 1;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 3, 'sent', NULL, 'Ich komme ursprünglich aus Spanien, aber jetzt wohne ich in Berlin.', 'I am originally from Spain, but now I live in Berlin.', 'من اصالتاً اهل اسپانیا هستم، ولی الان در برلین زندگی می‌کنم.', NULL, NULL FROM lessons WHERE day = 1;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 4, 'received', 'Interessant! Was machst du beruflich?', NULL, 'Interesting! What do you do for work?', 'جالبه! شغلت چیه؟', NULL, NULL FROM lessons WHERE day = 1;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 5, 'sent', NULL, 'Ich arbeite als Softwareentwickler.', 'I work as a software developer.', 'من برنامه‌نویس هستم.', NULL, NULL FROM lessons WHERE day = 1;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 6, 'received', 'Und was machst du in deiner Freizeit?', NULL, 'And what do you do in your free time?', 'و تو وقت آزادت چیکار می‌کنی؟', NULL, NULL FROM lessons WHERE day = 1;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 7, 'sent', NULL, 'Ich spiele gerne Fußball und reise sehr gerne.', 'I like playing football and love travelling.', 'فوتبال بازی می‌کنم و سفر کردن رو دوست دارم.', NULL, NULL FROM lessons WHERE day = 1;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 0, 'received', 'Hallo! Guten Morgen!', NULL, 'Hello! Good morning!', 'سلام! صبح بخیر!', NULL, NULL FROM lessons WHERE day = 2;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 1, 'sent', NULL, 'Guten Morgen! Wie geht es Ihnen?', 'Good morning! How are you?', 'صبح بخیر! حالتون چطوره؟', NULL, NULL FROM lessons WHERE day = 2;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 2, 'received', 'Danke, mir geht es gut. Und Ihnen?', NULL, 'Thanks, I''m fine. And you?', 'ممنون، حالم خوبه. و شما؟', NULL, NULL FROM lessons WHERE day = 2;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 3, 'sent', NULL, 'Auch gut, danke.', 'Also good, thanks.', 'منم خوبم، ممنون.', NULL, NULL FROM lessons WHERE day = 2;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 4, 'received', 'Schön, Sie zu treffen. Auf Wiedersehen!', NULL, 'Nice to meet you. Goodbye!', 'خوشحال شدم. خداحافظ!', NULL, NULL FROM lessons WHERE day = 2;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 5, 'sent', NULL, 'Auf Wiedersehen! Tschüss!', 'Goodbye! Bye!', 'خداحافظ! بای!', NULL, NULL FROM lessons WHERE day = 2;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 6, 'received', 'Es war schön, Sie kennenzulernen!', NULL, 'It was lovely meeting you!', 'از آشنایی با شما خوشحال شدم!', NULL, NULL FROM lessons WHERE day = 2;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 0, 'received', 'Hallo! Wie geht''s?', NULL, 'Hello! How are you?', 'سلام! چطوری؟', NULL, NULL FROM lessons WHERE day = 3;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 1, 'sent', NULL, 'Hallo! Es geht mir gut, danke.', 'Hello! I''m fine, thanks.', 'سلام! خوبم، ممنون.', NULL, NULL FROM lessons WHERE day = 3;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 2, 'received', 'Nur gut? Du siehst ein bisschen müde aus.', NULL, 'Just fine? You look a little tired.', 'فقط خوب؟ یه کم خسته به نظر می‌رسی.', NULL, NULL FROM lessons WHERE day = 3;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 3, 'sent', NULL, 'Ja, ich bin ein bisschen müde. Ich habe nicht gut geschlafen.', 'Yes, I am a little tired. I didn''t sleep well.', 'آره، یه کم خستم. خوب نخوابیدم.', NULL, NULL FROM lessons WHERE day = 3;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 4, 'received', 'Das kenne ich. Und wie geht es deiner Familie?', NULL, 'I know that feeling. And how is your family?', 'می‌فهمم. خانواده‌ات چطورن؟', NULL, NULL FROM lessons WHERE day = 3;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 5, 'sent', NULL, 'Denen geht es gut, danke der Nachfrage.', 'They''re fine, thanks for asking.', 'اونا خوبن، ممنون که پرسیدی.', NULL, NULL FROM lessons WHERE day = 3;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 6, 'received', 'Das ist schön. Erhol dich gut!', NULL, 'That''s great. Get some rest!', 'عالیه. استراحت کن!', NULL, NULL FROM lessons WHERE day = 3;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 7, 'sent', NULL, 'Danke! Dir auch einen schönen Tag.', 'Thanks! Have a nice day too.', 'ممنون! روز خوبی داشته باشی.', NULL, NULL FROM lessons WHERE day = 3;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 0, 'received', 'Wie alt bist du?', NULL, 'How old are you?', 'چند سالته؟', NULL, NULL FROM lessons WHERE day = 4;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 1, 'sent', NULL, 'Ich bin achtundzwanzig Jahre alt.', 'I am twenty-eight years old.', 'من ۲۸ سالمه.', NULL, NULL FROM lessons WHERE day = 4;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 2, 'received', 'Und wie ist deine Handynummer?', NULL, 'And what is your phone number?', 'شماره موبایلت چنده؟', NULL, NULL FROM lessons WHERE day = 4;
