INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 9, 'sent', NULL, 'Gerne. Bringen Sie mir dann noch ein Wasser.', 'Gladly. Then bring me a water too.', 'خواهش می‌کنم. پس یه آب هم برام بیارید.', NULL, NULL FROM lessons WHERE day = 45;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 10, 'received', 'Und möchten Sie ein Trinkgeld geben?', NULL, 'And would you like to leave a tip?', 'انعام هم می‌خواید بدید؟', NULL, NULL FROM lessons WHERE day = 45;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 11, 'sent', NULL, 'Ja, stimmt so. Der Kaffee war ausgezeichnet!', 'Yes, keep the change. The coffee was excellent!', 'آره، بقیه مال شما. قهوه‌ش عالی بود!', NULL, NULL FROM lessons WHERE day = 45;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 0, 'received', 'Hey, mein Geburtstag ist am Samstag. Kommst du zur Party?', NULL, 'Hey, my birthday is on Saturday. Are you coming to the party?', 'هی، تولدم شنبه‌ست. میای به پارتی؟', NULL, NULL FROM lessons WHERE day = 46;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 1, 'sent', NULL, 'Natürlich! Das würde ich nicht verpassen. Wo findet sie statt?', 'Of course! I wouldn''t miss it. Where is it?', 'البته! این رو از دست نمیدم. کجاست؟', NULL, NULL FROM lessons WHERE day = 46;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 2, 'received', 'Bei mir zu Hause, ab sieben Uhr abends.', NULL, 'At my place, starting at seven in the evening.', 'خونه‌ام، از ساعت هفت شب.', NULL, NULL FROM lessons WHERE day = 46;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 3, 'sent', NULL, 'Soll ich etwas mitbringen?', 'Should I bring something?', 'چیزی بیارم؟', NULL, NULL FROM lessons WHERE day = 46;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 4, 'received', 'Nur dich selbst! Aber Wein wäre willkommen.', NULL, 'Just bring yourself! But wine would be welcome.', 'فقط خودت بیا! ولی شراب هم خوشحال میشیم.', NULL, NULL FROM lessons WHERE day = 46;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 5, 'sent', NULL, 'Herzlichen Glückwunsch zum Geburtstag! Alles Gute für dich!', 'Happy birthday! All the best for you!', 'تولدت مبارک! همه چیز بهت خیر باشه!', NULL, NULL FROM lessons WHERE day = 46;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 6, 'received', 'Vielen herzlichen Dank! Ich freue mich so, dass du da bist.', NULL, 'Thank you so much! I''m so happy you''re here.', 'خیلی ممنون! خیلی خوشحالم که اینجایی.', NULL, NULL FROM lessons WHERE day = 46;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 7, 'sent', NULL, 'Hier, das ist für dich. Ich hoffe, es gefällt dir.', 'Here, this is for you. I hope you like it.', 'بفرما، این برای توئه. امیدوارم خوشت بیاد.', NULL, NULL FROM lessons WHERE day = 46;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 8, 'received', 'Oh, wie schön! Das wäre doch nicht nötig gewesen!', NULL, 'Oh, how lovely! You shouldn''t have!', 'اوه، چه قشنگ! لازم نبود زحمت بکشی!', NULL, NULL FROM lessons WHERE day = 46;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 9, 'sent', NULL, 'Wie alt wirst du heute?', 'How old are you turning today?', 'امروز چند سالت میشه؟', NULL, NULL FROM lessons WHERE day = 46;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 10, 'received', 'Ich werde dreißig. Ich kann es kaum glauben!', NULL, 'I''m turning thirty. I can''t believe it!', 'سی سالم میشه. باورم نمیشه!', NULL, NULL FROM lessons WHERE day = 46;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 11, 'sent', NULL, 'Der Kuchen sieht toll aus. Hast du ihn selbst gebacken?', 'The cake looks amazing. Did you bake it yourself?', 'کیک خیلی قشنگه. خودت پختیش؟', NULL, NULL FROM lessons WHERE day = 46;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 12, 'received', 'Nein, meine Mutter hat ihn gebacken. Er ist aus Schokolade.', NULL, 'No, my mom baked it. It''s chocolate.', 'نه، مامانم پخته. شکلاتیه.', NULL, NULL FROM lessons WHERE day = 46;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 13, 'sent', NULL, 'Lass uns anstoßen! Auf deine Gesundheit!', 'Let''s make a toast! To your health!', 'بیاید乾杯 کنیم! به سلامتیت!', NULL, NULL FROM lessons WHERE day = 46;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 14, 'received', 'Prost! Ich freue mich so, dass alle hier sind.', NULL, 'Cheers! I''m so glad everyone is here.', 'به سلامتی! خیلی خوشحالم که همه اینجان.', NULL, NULL FROM lessons WHERE day = 46;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 15, 'sent', NULL, 'Es war ein wunderschöner Abend. Danke für die Einladung!', 'It was a wonderful evening. Thank you for the invitation!', 'شب فوق‌العاده‌ای بود. ممنون از دعوتت!', NULL, NULL FROM lessons WHERE day = 46;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 16, 'received', 'Danke, dass du gekommen bist. Bis bald!', NULL, 'Thank you for coming. See you soon!', 'ممنون که اومدی. به زودی میبینمت!', NULL, NULL FROM lessons WHERE day = 46;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 0, 'received', 'Möchtest du heute Abend ins Kino gehen?', NULL, 'Would you like to go to the cinema tonight?', 'امشب دوست داری بریم سینما؟', NULL, NULL FROM lessons WHERE day = 47;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 1, 'sent', NULL, 'Ja, gerne! Was läuft gerade?', 'Yes, I''d love to! What''s on?', 'آره، خوشحال می‌شم! چی داره نشون می‌ده؟', NULL, NULL FROM lessons WHERE day = 47;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 2, 'received', 'Ein neuer Thriller läuft um neunzehn Uhr und um einundzwanzig Uhr.', NULL, 'A new thriller is showing at seven and at nine.', 'یه هیجانی جدید ساعت هفت و ساعت نه نشون می‌ده.', NULL, NULL FROM lessons WHERE day = 47;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 3, 'sent', NULL, 'Ich bevorzuge den frühen. Kann ich zwei Karten online kaufen?', 'I prefer the early showing. Can I buy two tickets online?', 'نمایش زودتر رو ترجیح می‌دم. می‌تونم دو تا بلیت آنلاین بخرم؟', NULL, NULL FROM lessons WHERE day = 47;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 4, 'received', 'Ja, auf der Website des Kinos.', NULL, 'Yes, on the cinema''s website.', 'آره، از سایت سینما.', NULL, NULL FROM lessons WHERE day = 47;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 5, 'sent', NULL, 'Sollen wir Sitzplätze reservieren oder kommt man ohne rein?', 'Should we reserve seats or can you get in without?', 'جا رزرو کنیم یا بدون رزرو هم می‌شه رفت؟', NULL, NULL FROM lessons WHERE day = 47;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 6, 'received', 'Am Wochenende ist es voll — besser reservieren.', NULL, 'On the weekend it''s crowded — better to reserve.', 'آخر هفته شلوغه — بهتره رزرو کنی.', NULL, NULL FROM lessons WHERE day = 47;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 7, 'sent', NULL, 'Ok, ich reserviere Plätze in der Mitte.', 'Ok, I''ll reserve seats in the middle.', 'باشه، وسط جا رزرو می‌کنم.', NULL, NULL FROM lessons WHERE day = 47;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 8, 'received', 'Wollen wir vorher noch etwas essen?', NULL, 'Do we want to eat something beforehand?', 'قبلش یه چیزی بخوریم؟', NULL, NULL FROM lessons WHERE day = 47;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 9, 'sent', NULL, 'Ja! Treffen wir uns um achtzehn Uhr beim Restaurant nebenan.', 'Yes! Let''s meet at six at the restaurant next door.', 'آره! ساعت شش جلوی رستوران کناری همدیگه رو ببینیم.', NULL, NULL FROM lessons WHERE day = 47;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 10, 'received', 'Perfekt. Ich freue mich!', NULL, 'Perfect. I''m looking forward to it!', 'عالی. منتظرشم!', NULL, NULL FROM lessons WHERE day = 47;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 11, 'sent', NULL, 'Ich auch! Bis heute Abend.', 'Me too! See you tonight.', 'منم! تا امشب.', NULL, NULL FROM lessons WHERE day = 47;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 0, 'received', 'Deine neue Jacke sieht toll aus!', NULL, 'Your new jacket looks great!', 'ژاکت جدیدت خیلی قشنگه!', NULL, NULL FROM lessons WHERE day = 48;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 1, 'sent', NULL, 'Danke schön! Ich habe sie letzte Woche gekauft.', 'Thank you! I bought it last week.', 'خیلی ممنون! هفته پیش خریدمش.', NULL, NULL FROM lessons WHERE day = 48;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 2, 'received', 'Wie lange wohnst du schon in Berlin?', NULL, 'How long have you been living in Berlin?', 'چقدره داری تو برلین زندگی می‌کنی؟', NULL, NULL FROM lessons WHERE day = 48;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 3, 'sent', NULL, 'Seit zwei Jahren. Ich liebe diese Stadt.', 'For two years. I love this city.', 'دو ساله. عاشق این شهرم.', NULL, NULL FROM lessons WHERE day = 48;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 4, 'received', 'Hast du Familie hier?', NULL, 'Do you have family here?', 'اینجا خانواده داری؟', NULL, NULL FROM lessons WHERE day = 48;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 5, 'sent', NULL, 'Nein, meine Familie lebt noch in Spanien. Ich besuche sie zweimal im Jahr.', 'No, my family still lives in Spain. I visit them twice a year.', 'نه، خانواده‌ام هنوز اسپانیاست. سالی دوبار می‌رم پیششون.', NULL, NULL FROM lessons WHERE day = 48;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 6, 'received', 'Das klingt schön. Was vermisst du am meisten?', NULL, 'That sounds nice. What do you miss most?', 'قشنگه. چی رو بیشتر از همه دلت می‌خواد؟', NULL, NULL FROM lessons WHERE day = 48;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 7, 'sent', NULL, 'Das Essen und das Wetter! In Spanien ist es viel wärmer.', 'The food and the weather! In Spain it''s much warmer.', 'غذا و آب‌وهوا! اسپانیا خیلی گرمتره.', NULL, NULL FROM lessons WHERE day = 48;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 8, 'received', 'Das verstehe ich! Aber Berlin hat auch seinen Charme.', NULL, 'I understand that! But Berlin also has its charm.', 'می‌فهمم! ولی برلین هم جذابیت خودشو داره.', NULL, NULL FROM lessons WHERE day = 48;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 9, 'sent', NULL, 'Absolut! Die Menschen hier sind sehr freundlich.', 'Absolutely! The people here are very friendly.', 'کاملاً! مردم اینجا خیلی مهربانن.', NULL, NULL FROM lessons WHERE day = 48;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 10, 'received', 'Das ist das Schönste an dieser Stadt, finde ich.', NULL, 'That''s the most beautiful thing about this city, I think.', 'به نظرم این قشنگ‌ترین چیز این شهره.', NULL, NULL FROM lessons WHERE day = 48;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 11, 'sent', NULL, 'Da stimme ich dir völlig zu.', 'I completely agree with you.', 'کاملاً باهات موافقم.', NULL, NULL FROM lessons WHERE day = 48;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 0, 'received', 'Was hast du dieses Wochenende vor?', NULL, 'What are your plans for this weekend?', 'آخر هفته چه برنامه‌ای داری؟', NULL, NULL FROM lessons WHERE day = 49;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 1, 'sent', NULL, 'Ich weiß noch nicht genau. Vielleicht machen wir einen Ausflug.', 'I don''t know exactly yet. Maybe we''ll go on a trip.', 'هنوز دقیقاً نمی‌دونم. شاید یه گردش کوتاه بریم.', NULL, NULL FROM lessons WHERE day = 49;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 2, 'received', 'Wohin möchtest du fahren?', NULL, 'Where would you like to go?', 'کجا می‌خوای بری؟', NULL, NULL FROM lessons WHERE day = 49;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 3, 'sent', NULL, 'Ich dachte an den Wannsee. Ein schöner Tag am See wäre super.', 'I thought of Wannsee. A nice day at the lake would be great.', 'به وانزه فکر کردم. یه روز قشنگ کنار دریاچه عالی می‌شه.', NULL, NULL FROM lessons WHERE day = 49;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 4, 'received', 'Gute Idee! Sollen wir wandern gehen?', NULL, 'Good idea! Shall we go hiking?', 'ایده خوبیه! کوه‌پیمایی بریم؟', NULL, NULL FROM lessons WHERE day = 49;
