INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 8, 'received', 'Toll! Ich bringe Getränke mit.', NULL, 'Great! I''ll bring drinks.', 'عالی! نوشیدنی می‌آرم.', NULL, NULL FROM lessons WHERE day = 49;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 9, 'sent', NULL, 'Perfekt. Es wird ein schöner Tag!', 'Perfect. It''s going to be a lovely day!', 'عالی. یه روز قشنگ می‌شه!', NULL, NULL FROM lessons WHERE day = 49;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 10, 'received', 'Ich freue mich schon. Bis Samstag!', NULL, 'I''m already looking forward to it. Until Saturday!', 'منتظرشم. تا شنبه!', NULL, NULL FROM lessons WHERE day = 49;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 11, 'sent', NULL, 'Bis dann! Schönen Abend noch.', 'See you then! Have a nice evening.', 'تا اون موقع! شب خوشی داشته باشی.', NULL, NULL FROM lessons WHERE day = 49;
