INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 6, 'sent', NULL, 'Ist das Frühstück inklusive?', 'Is breakfast included?', 'صبحانه شامل میشه؟', NULL, NULL FROM lessons WHERE day = 50;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 7, 'received', 'Ja. Und wir haben kostenloses WLAN.', NULL, 'Yes. And we have free Wifi.', 'بله. و وای‌فای رایگان داریم.', NULL, NULL FROM lessons WHERE day = 50;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 8, 'sent', NULL, 'Super, ich nehme es.', 'Great, I''ll take it.', 'عالی، میگیرمش.', NULL, NULL FROM lessons WHERE day = 50;
