INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 0, 'sent', NULL, 'Guten Tag, ich möchte dieses Paket in den Iran schicken.', 'Good day, I''d like to send this package to Iran.', 'روز بخیر، می‌خوام این بسته رو به ایران بفرستم.', NULL, NULL FROM lessons WHERE day = 52;
