INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 2, 'sent', NULL, 'Wie viel wiegt es?', 'How much does it weigh?', 'چقدر وزن داره؟', NULL, NULL FROM lessons WHERE day = 52;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 3, 'received', 'Einkommazwei Kilogramm. Wohin genau soll es geliefert werden?', NULL, '1.2 kilograms. Where exactly should it be delivered?', 'یک و دو دهم کیلوگرم. دقیقاً کجا باید تحویل داده بشه؟', NULL, NULL FROM lessons WHERE day = 52;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 4, 'sent', NULL, 'Nach Teheran. Es ist ein Geschenk für meine Familie.', 'To Tehran. It''s a gift for my family.', 'به تهران. یه هدیه برای خانواده‌امه.', NULL, NULL FROM lessons WHERE day = 52;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 5, 'received', 'Möchten Sie Standardversand oder Express?', NULL, 'Would you like standard or express shipping?', 'ارسال معمولی می‌خواید یا اکسپرس؟', NULL, NULL FROM lessons WHERE day = 52;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 6, 'sent', NULL, 'Was ist der Unterschied bei der Lieferzeit?', 'What''s the difference in delivery time?', 'فرق زمان تحویل چقدره؟', NULL, NULL FROM lessons WHERE day = 52;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 7, 'received', 'Standard dauert zehn bis vierzehn Tage, Express drei bis fünf Tage.', NULL, 'Standard takes 10 to 14 days, express 3 to 5 days.', 'معمولی ده تا چهارده روز، اکسپرس سه تا پنج روز.', NULL, NULL FROM lessons WHERE day = 52;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 8, 'sent', NULL, 'Ich nehme Express, bitte. Was kostet das?', 'I''ll take express, please. How much does it cost?', 'اکسپرس رو می‌خوام، لطفاً. چقدر میشه؟', NULL, NULL FROM lessons WHERE day = 52;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 9, 'received', 'Express in den Iran kostet achtundzwanzig Euro.', NULL, 'Express to Iran costs 28 euros.', 'اکسپرس به ایران بیست و هشت یورو میشه.', NULL, NULL FROM lessons WHERE day = 52;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 10, 'sent', NULL, 'In Ordnung. Kann ich das Paket versichern lassen?', 'Fine. Can I insure the package?', 'باشه. میتونم بسته رو بیمه کنم؟', NULL, NULL FROM lessons WHERE day = 52;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 11, 'received', 'Ja, für fünf Euro zusätzlich bis zu einem Warenwert von hundert Euro.', NULL, 'Yes, for an additional 5 euros up to 100 euros in value.', 'بله، پنج یورو اضافه تا ارزش صد یورو.', NULL, NULL FROM lessons WHERE day = 52;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 12, 'sent', NULL, 'Ja bitte, ich versichere es. Der Inhalt ist etwa achtzig Euro wert.', 'Yes please, I''ll insure it. The contents are worth about 80 euros.', 'بله لطفاً، بیمه‌اش می‌کنم. محتوا حدود هشتاد یورو ارزش داره.', NULL, NULL FROM lessons WHERE day = 52;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 13, 'received', 'Gut. Füllen Sie bitte diese Zollerklärung aus.', NULL, 'Good. Please fill out this customs declaration.', 'خوب. لطفاً این فرم گمرکی رو پر کنید.', NULL, NULL FROM lessons WHERE day = 52;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 14, 'sent', NULL, 'Schreibe ich den Inhalt auf Deutsch oder auf Englisch?', 'Do I write the contents in German or English?', 'محتوا رو به آلمانی بنویسم یا انگلیسی؟', NULL, NULL FROM lessons WHERE day = 52;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 15, 'received', 'Deutsch oder Englisch, beides wird akzeptiert.', NULL, 'German or English, both are accepted.', 'آلمانی یا انگلیسی، هر دو قبوله.', NULL, NULL FROM lessons WHERE day = 52;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 16, 'sent', NULL, 'Bitte schön, alles ausgefüllt.', 'Here you go, all filled out.', 'بفرمایید، همه چیز پر شد.', NULL, NULL FROM lessons WHERE day = 52;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 17, 'received', 'Perfekt. Hier ist Ihre Sendungsnummer. Sie können das Paket online verfolgen.', NULL, 'Perfect. Here is your tracking number. You can track the package online.', 'عالی. اینم شماره رهگیری شما. می‌تونید بسته رو آنلاین ردیابی کنید.', NULL, NULL FROM lessons WHERE day = 52;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 0, 'sent', NULL, 'Guten Tag, ich möchte einen Mietwagen.', 'Good day, I''d like to rent a car.', 'روز بخیر، می‌خوام یه ماشین اجاره کنم.', NULL, NULL FROM lessons WHERE day = 53;
