INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 8, 'sent', NULL, 'Wie lange ist die Mindestlaufzeit?', 'How long is the minimum lease?', 'حداقل مدت قرارداد چقدره؟', NULL, NULL FROM lessons WHERE day = 56;
