INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 12, 'sent', NULL, 'Ab wann wäre die Wohnung verfügbar?', 'When would the apartment be available?', 'آپارتمان از کی آزاده؟', NULL, NULL FROM lessons WHERE day = 56;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 13, 'received', 'Ab dem ersten des nächsten Monats.', NULL, 'From the first of next month.', 'از اول ماه آینده.', NULL, NULL FROM lessons WHERE day = 56;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 14, 'sent', NULL, 'Sie gefällt mir sehr gut. Ich würde sie gerne nehmen.', 'I really like it. I''d like to take it.', 'خیلی دوستش دارم. می‌خوام بگیرمش.', NULL, NULL FROM lessons WHERE day = 56;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 15, 'received', 'Sehr gut! Ich schicke Ihnen den Mietvertrag zu.', NULL, 'Great! I''ll send you the rental contract.', 'عالی! قرارداد اجاره رو برای شما می‌فرستم.', NULL, NULL FROM lessons WHERE day = 56;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 0, 'sent', NULL, 'Hallo, ich habe ein Problem mit meinem Internet. Es funktioniert nicht.', 'Hello, I have a problem with my internet. It''s not working.', 'سلام، با اینترنتم مشکل دارم. کار نمیکنه.', NULL, NULL FROM lessons WHERE day = 57;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 1, 'received', 'Guten Tag. Was genau ist das Problem?', NULL, 'Good day. What exactly is the problem?', 'روز بخیر. مشکل دقیقاً چیه؟', NULL, NULL FROM lessons WHERE day = 57;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 2, 'sent', NULL, 'Die Verbindung bricht immer wieder ab. Der Router zeigt ein rotes Licht.', 'The connection keeps dropping. The router shows a red light.', 'اتصال قطع و وصل میشه. روتر چراغ قرمز نشون میده.', NULL, NULL FROM lessons WHERE day = 57;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 3, 'received', 'Haben Sie versucht, den Router neu zu starten?', NULL, 'Have you tried restarting the router?', 'روتر رو ریستارت کردید؟', NULL, NULL FROM lessons WHERE day = 57;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 4, 'sent', NULL, 'Ja, ich habe ihn bereits zweimal neu gestartet.', 'Yes, I''ve already restarted it twice.', 'بله، دوبار ریستارتش کردم.', NULL, NULL FROM lessons WHERE day = 57;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 5, 'received', 'Seit wann besteht das Problem?', NULL, 'How long has this problem been going on?', 'از کی این مشکل رو دارید؟', NULL, NULL FROM lessons WHERE day = 57;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 6, 'sent', NULL, 'Seit gestern Abend. Ich arbeite im Homeoffice und brauche dringend Internet.', 'Since yesterday evening. I work from home and urgently need the internet.', 'از دیشب. من دورکاری می‌کنم و فوری به اینترنت نیاز دارم.', NULL, NULL FROM lessons WHERE day = 57;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 7, 'received', 'Ich sehe eine Störung in Ihrer Region. Wir arbeiten daran.', NULL, 'I can see an outage in your area. We''re working on it.', 'تو منطقه شما اختلال میبینم. داریم روش کار می‌کنیم.', NULL, NULL FROM lessons WHERE day = 57;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 8, 'sent', NULL, 'Wann wird das Problem behoben?', 'When will it be fixed?', 'کِی درست میشه؟', NULL, NULL FROM lessons WHERE day = 57;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 9, 'received', 'Voraussichtlich innerhalb von zwei Stunden.', NULL, 'Probably within two hours.', 'احتمالاً ظرف دو ساعت.', NULL, NULL FROM lessons WHERE day = 57;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 10, 'sent', NULL, 'Außerdem entlädt sich mein Handy-Akku sehr schnell.', 'Also, my phone battery drains very quickly.', 'ضمناً باتری گوشیم خیلی سریع خالی میشه.', NULL, NULL FROM lessons WHERE day = 57;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 11, 'received', 'Das ist eine andere Abteilung. Soll ich Sie verbinden?', NULL, 'That''s a different department. Shall I connect you?', 'اون بخش دیگه‌ایه. وصلتون کنم؟', NULL, NULL FROM lessons WHERE day = 57;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 12, 'sent', NULL, 'Nein danke, ich rufe später zurück. Kann ich eine Ticketnummer bekommen?', 'No thanks, I''ll call back later. Can I get a ticket number?', 'نه ممنون، بعداً زنگ میزنم. میتونم یه شماره تیکت بگیرم؟', NULL, NULL FROM lessons WHERE day = 57;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 13, 'received', 'Natürlich. Ihre Ticketnummer ist 4872.', NULL, 'Of course. Your ticket number is 4872.', 'البته. شماره تیکت شما ۴۸۷۲ هست.', NULL, NULL FROM lessons WHERE day = 57;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 14, 'sent', NULL, 'Danke. Ich warte auf Ihre Rückmeldung.', 'Thank you. I''ll wait for your update.', 'ممنون. منتظر خبرتون میمونم.', NULL, NULL FROM lessons WHERE day = 57;
