INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 0, 'sent', NULL, 'Ich habe meinen Zug verpasst.', 'I missed my train.', 'قطارم رو از دست دادم.', NULL, NULL FROM lessons WHERE day = 58;
