INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 0, 'received', 'Guten Tag, bitte nehmen Sie Platz.', NULL, 'Good day, please take a seat.', 'روز بخیر، بفرمایید بنشینید.', NULL, NULL FROM lessons WHERE day = 59;
