INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 2, 'sent', NULL, 'Mein Geldbeutel wurde gestohlen. In der U-Bahn.', 'My wallet was stolen. On the subway.', 'کیف پولم دزدیده شد. تو مترو.', NULL, NULL FROM lessons WHERE day = 60;
